package dev.veltraph.client.combat.ghost;

import dev.veltraph.client.game.GameArea;
import dev.veltraph.client.world.Vec3;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GhostWarpPermitTest {
    final Object player=new Object(),world=new Object(),connection=new Object(),owner=new Object();final UUID uuid=UUID.randomUUID();
    final Vec3 anchor=new Vec3(8.5,70,.5);final GhostPreflightProfile profile=new GhostPreflightProfile("private_warp","Denied",anchor,10000,false,0,null);
    final GhostWarpPermit permit=new GhostWarpPermit(player,world,connection,uuid,profile,"minecraft:overworld",4,100,10100);
    boolean arrival(Object p,Object w,Object c,UUID id,GameArea a,String dim,Vec3 feet,long serial,Vec3 receipt,long now){return permit.arrival(p,w,c,id,true,true,true,a,dim,feet,serial,receipt,now);}
    @Test void actualNewReceiptRequiredEvenWhenAlreadyAtAnchor(){assertFalse(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,4,anchor,200));assertTrue(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,anchor,200));}
    @Test void receiptAndCurrentBodyMustBothMeetStrictSourceOneBlockRadius(){assertFalse(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",new Vec3(9.5,70,.5),5,anchor,200));assertFalse(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,new Vec3(8.9,70,.5),200));}
    @Test void replacementRequiresSameConnectionUuidAndRouteDimension(){assertTrue(arrival(new Object(),new Object(),connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,anchor,200));assertFalse(arrival(new Object(),new Object(),new Object(),uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,anchor,200));assertFalse(arrival(player,world,connection,UUID.randomUUID(),GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,anchor,200));assertFalse(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:the_nether",anchor,5,anchor,200));}
    @Test void expiredFutureNonfiniteOrWrongAreaCannotCommit(){assertFalse(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,anchor,99));assertFalse(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,anchor,10101));assertFalse(arrival(player,world,connection,uuid,GameArea.GARDEN,"minecraft:overworld",anchor,5,anchor,200));assertFalse(arrival(player,world,connection,uuid,GameArea.DWARVEN_MINES,"minecraft:overworld",new Vec3(Double.NaN,70,0),5,anchor,200));}
    InstalledGhostWarpLifecycle captured(){var flow=new InstalledGhostWarpLifecycle();assertTrue(flow.capture(owner,owner,1,true,permit,player,world,connection,uuid,GameArea.GARDEN,100));return flow;}
    InstalledGhostWarpLifecycle.Observation observation(long serial){return new InstalledGhostWarpLifecycle.Observation(player,world,connection,uuid,true,true,true,true,false,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,serial,anchor,false,200);}
    @Test void rootWaitsUntilNewerReceiptAndCommitsOnlyExactOwnerPermit(){var flow=captured();assertEquals(InstalledGhostWarpLifecycle.Decision.WAIT,flow.evaluate(owner,owner,1,true,permit,observation(4)));assertEquals(InstalledGhostWarpLifecycle.Decision.COMMIT,flow.evaluate(owner,owner,1,true,permit,observation(5)));assertEquals(InstalledGhostWarpLifecycle.Decision.STOP,flow.evaluate(owner,new Object(),1,true,permit,observation(5)));}
    @Test void rootCancellationAndDenialNeverBecomeArrival(){var flow=captured();assertTrue(flow.denial(owner,permit,"Denied",200));assertTrue(flow.denial(owner,permit,"dEnIeD",200));assertFalse(flow.denial(owner,permit,"prefix Denied",200));assertEquals(InstalledGhostWarpLifecycle.Decision.STOP,flow.evaluate(owner,owner,1,false,permit,observation(5)));flow.clear();assertEquals(InstalledGhostWarpLifecycle.Decision.INACTIVE,flow.evaluate(owner,owner,1,true,permit,observation(5)));}
    @Test void replacementWithoutCurrentReceiptWaitsInsteadOfReusingOldWorldSerial(){var flow=captured();var o=new InstalledGhostWarpLifecycle.Observation(new Object(),new Object(),connection,uuid,true,true,true,true,false,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,null,false,200);assertEquals(InstalledGhostWarpLifecycle.Decision.WAIT,flow.evaluate(owner,owner,1,true,permit,o));}
    @Test void rootAcceptsNewerSameActivationPermitAndRejectsRetiredPermit(){var flow=captured();var ticket=new GhostTransportLoop.Attempt(permit.activation(),2,301,permit.expiresAt());var next=new GhostWarpPermit(player,world,connection,uuid,profile,"minecraft:overworld",5,301,permit.expiresAt(),ticket);var o=new InstalledGhostWarpLifecycle.Observation(player,world,connection,uuid,true,true,true,true,false,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,6,anchor,false,302);assertEquals(InstalledGhostWarpLifecycle.Decision.COMMIT,flow.evaluate(owner,owner,1,true,next,ticket,o));assertSame(next,flow.permit());assertEquals(InstalledGhostWarpLifecycle.Decision.STOP,flow.evaluate(owner,owner,1,true,permit,permit.attempt(),o));}
    @Test void falseNativeDispatchWaitsButCannotBorrowOldReceipt(){var flow=captured();var ticket=new GhostTransportLoop.Attempt(permit.activation(),2,301,permit.expiresAt());var o=new InstalledGhostWarpLifecycle.Observation(player,world,connection,uuid,true,true,true,true,false,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,5,anchor,false,302);assertEquals(InstalledGhostWarpLifecycle.Decision.WAIT,flow.evaluate(owner,owner,1,true,null,ticket,o));}
    @Test void falseDispatchDoesNotGrantWrongRealmReplacementWait(){var flow=captured();var ticket=new GhostTransportLoop.Attempt(permit.activation(),2,301,permit.expiresAt());var o=new InstalledGhostWarpLifecycle.Observation(new Object(),new Object(),connection,uuid,true,true,true,true,false,GameArea.GARDEN,"minecraft:overworld",anchor,4,null,false,302);assertEquals(InstalledGhostWarpLifecycle.Decision.STOP,flow.evaluate(owner,owner,1,true,null,ticket,o));}
    @Test void retryCannotChangeActivationDeadlineContextOrReceiptFloor(){var flow=captured();var ticket=new GhostTransportLoop.Attempt(new Object(),2,301,permit.expiresAt());var next=new GhostWarpPermit(player,world,connection,uuid,profile,"minecraft:overworld",5,301,permit.expiresAt(),ticket);var o=new InstalledGhostWarpLifecycle.Observation(player,world,connection,uuid,true,true,true,true,false,GameArea.DWARVEN_MINES,"minecraft:overworld",anchor,6,anchor,false,302);assertEquals(InstalledGhostWarpLifecycle.Decision.STOP,flow.evaluate(owner,owner,1,true,next,ticket,o));}
    @Test void rootRejectsForeignIdentityAndMultipleControllerAdmission(){var f=new InstalledGhostWarpLifecycle();assertFalse(f.capture(owner,owner,2,true,permit,player,world,connection,uuid,GameArea.GARDEN,100));assertFalse(f.capture(owner,owner,1,true,permit,player,new Object(),connection,uuid,GameArea.GARDEN,100));}
}
